import React, { useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmAddCurso = ({ onClose, onSave }) => {
  const [curso, setCurso] = useState({
    nome: "",
    nivel: "",
    periodo: "",
    area: "",
  });

  const handleChange = (e) => {
    setCurso({ ...curso, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSave(curso);
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <ul className="nav nav-tabs justify-content-center mt-3">
        <li className="nav-item mx-2">
          <a className="nav-link active" href="#">
            Cursos
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Professores
          </a>
        </li>
        <li className="nav-item mx-2">
          <a className="nav-link" href="#">
            Alunos
          </a>
        </li>
      </ul>

      <div className="d-flex justify-content-center mt-4">
        <form
          className="bg-white p-4 rounded shadow"
          style={{ width: "400px" }}
          onSubmit={handleSubmit}
        >
          <input
            type="text"
            name="nome"
            className="form-control mb-3"
            placeholder="Nome"
            value={curso.nome}
            onChange={handleChange}
            required
          />

          {/* Select estilizado */}
          <div className="custom-select">
            <select
              name="nivel"
              className="form-control mb-3"
              value={curso.nivel}
              onChange={handleChange}
              required
            >
              <option value="">Nível</option>
              <option value="Básico">Básico</option>
              <option value="Intermediário">Intermediário</option>
              <option value="Avançado">Avançado</option>
            </select>
          </div>

          <div className="custom-select">
            <select
              name="periodo"
              className="form-control mb-3"
              value={curso.periodo}
              onChange={handleChange}
              required
            >
              <option value="">Período</option>
              <option value="Matutino">Matutino</option>
              <option value="Vespertino">Vespertino</option>
              <option value="Noturno">Noturno</option>
            </select>
          </div>

          <div className="custom-select">
            <select
              name="area"
              className="form-control mb-3"
              value={curso.area}
              onChange={handleChange}
              required
            >
              <option value="">Área</option>
              <option value="Exatas">Exatas</option>
              <option value="Humanas">Humanas</option>
              <option value="Biológicas">Biológicas</option>
            </select>
          </div>

          <div className="d-flex justify-content-between">
            <button type="button" className="btn btn-danger" onClick={onClose}>
              cancelar
            </button>
            <button type="submit" className="btn btn-primary">
              salvar
            </button>
          </div>
        </form>
      </div>

      {/* Estilização da seta personalizada */}
      <style>{`
        .custom-select {
          position: relative;
        }

        .custom-select select {
          appearance: none;
          -webkit-appearance: none;
          -moz-appearance: none;
          background-image: url("data:image/svg+xml;charset=UTF-8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 20 20' fill='%23000000'%3E%3Cpath fill-rule='evenodd' d='M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z' clip-rule='evenodd'/%3E%3C/svg%3E");
          background-repeat: no-repeat;
          background-position: right 10px center;
          background-size: 16px;
          padding-right: 30px;
        }
      `}</style>
    </div>
  );
};

export default AdmAddCurso;
